class Dog {
  bark(): string {
    return "Woof";
  }
}

class Cat {
  meow(): string {
    return "Meow";
  }
}

function speak(pet: Dog | Cat): string {
  return pet instanceof Dog ? pet.bark() : pet.meow();
}

interface Fish {
  swim(): void;
}

interface Bird {
  fly(): void;
}

function isFish(animal: Fish | Bird): animal is Fish {
  return "swim" in animal;
}

const animals: (Fish | Bird)[] = [{ swim() {} }, { fly() {} }, { swim() {} }];
const swimmers = animals.filter(isFish);

const values: (string | null)[] = ["a", null, "b"];
const strings = values.filter((v) => v !== null);

console.log(speak(new Dog()), speak(new Cat()));
console.log(swimmers.length, strings);

